-- mod-playerbots-bis : les items, par classe / spe / slot / palier.
--
-- spec = onglet de talents : 0 = premier arbre, 1 = deuxieme, 2 = troisieme.
--   Guerrier   0 Armes       1 Fureur       2 Protection
--   Paladin    0 Sacre       1 Protection   2 Vindicte
--   Chasseur   0 Maitrise    1 Precision    2 Survie
--   Voleur     0 Assassinat  1 Combat       2 Subtilite
--   Pretre     0 Discipline  1 Sacre        2 Ombre
--   DK         0 Sang        1 Givre        2 Impie
--   Chaman     0 Elementaire 1 Amelioration 2 Restauration
--   Mage       0 Arcane      1 Feu          2 Givre
--   Demoniste  0 Affliction  1 Demonologie  2 Destruction
--   Druide     0 Equilibre   1 Farouche Cat 2 Restauration   10 Farouche Ours
--
-- Le druide ours porte la spe 10 : il partage l'onglet 1 avec le chat, le module
-- l'aiguille vers 10 quand le bot a la strategie tank.
--
-- slot : enumeration EquipmentSlots d'AzerothCore
--   head=0 neck=1 shoulders=2 chest=4 waist=5 legs=6 feet=7 wrists=8 hands=9
--   finger1=10 finger2=11 trinket1=12 trinket2=13 back=14 mainhand=15 offhand=16 ranged=17
--   Pour les anneaux et bijoux une seule ligne suffit : le module compare
--   automatiquement avec les deux emplacements de la paire.
--
-- rank : ordre de priorite DANS un meme slot et un meme palier, 1 = le meilleur.
--   Un palier superieur bat toujours un rank meilleur d'un palier inferieur.
--
-- faction : 0 = les deux, 1 = Alliance, 2 = Horde. Une ligne de faction ecrase
--   la ligne neutre pour le meme item.
--
-- CONTENU : ces lignes sont converties depuis la table playerbots_bis_gear de
-- mod-playerbots (item ids et noms d'origine), repartis sur l'echelle de paliers.
-- Voir tools/convert_playerbots_bis_gear.py pour regenerer, et le README pour la
-- liste des paliers et des spes encore vides.

DROP TABLE IF EXISTS `playerbots_bis_item`;
CREATE TABLE `playerbots_bis_item` (
    `class`    TINYINT UNSIGNED NOT NULL,
    `spec`     TINYINT UNSIGNED NOT NULL,
    `slot`     TINYINT UNSIGNED NOT NULL,
    `faction`  TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `tier_id`  SMALLINT UNSIGNED NOT NULL,
    `item_id`  INT UNSIGNED NOT NULL,
    `rank`     TINYINT UNSIGNED NOT NULL DEFAULT 1,
    `comment`  VARCHAR(160) NOT NULL DEFAULT '',
    PRIMARY KEY (`class`, `spec`, `slot`, `faction`, `tier_id`, `item_id`),
    KEY `idx_lookup` (`class`, `spec`, `faction`),
    CONSTRAINT `fk_bis_item_tier` FOREIGN KEY (`tier_id`) REFERENCES `playerbots_bis_tier` (`tier_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

